export function isDocTypeInvoice(doc_type: string) {
  if (
    doc_type == 'INVOICE' ||
    doc_type == 'DELIVERY_NOTE' ||
    doc_type == 'ORDER_CONFIRMATION' ||
    doc_type == 'CUSTOMER_ORDERS'
  ) {
    return true;
  }
  return false;
}

export function isInvoice(doc_type: string) {
  if (doc_type == 'INVOICE') return true;
  else return false;
}

